Polling Details.swql:
SELECT NodeID, Caption, ObjectSubType, PollInterval, StatCollection, RediscoveryInterval,
       NextPoll, LastSync, EngineID, Community
FROM Orion.Nodes WHERE NodeID = ${node_id}

All IP Addresses.swql:
SELECT SUB.IPAddressType, SUB.IP_Address2 AS IP_Address
FROM (
  SELECT IP_Address AS IP_Address2, IPAddressType, ${node_id} AS IPOrder FROM Orion.Nodes WHERE NodeID = ${node_id}
  UNION (
    SELECT ni.IPAddress AS IP_Address2, ni.IPAddressType, 2 AS IPOrder
    FROM Orion.NodeIPAddresses ni
    JOIN Orion.Nodes n ON ni.NodeID = n.NodeID AND n.IP_Address != ni.IPAddress
    WHERE ni.NodeID = ${node_id}
  )
) SUB
ORDER BY SUB.IPOrder

Availability Statistics.swql:
SELECT NodeID, Caption, ResponseTime, PercentLoss, CPULoad, PercentMemoryUsed,
       Status, StatusDescription
FROM Orion.Nodes WHERE NodeID = ${node_id}
